// Create a Delaunay triangulation of the points
    Delaunay_triangulation_2 dt;
    for (const auto& point : points) {
        dt.insert(point);
    }

    // Select the triangles that have a circumradius less than or equal to the alpha value
    std::vector<Triangle_2> triangles;
    for (auto it = dt.finite_faces_begin(); it != dt.finite_faces_end(); ++it) {
        Triangle_2 triangle = it->triangle();
        double circumradius = triangle.circumradius();
        if (circumradius <= alpha) {
            triangles.push_back(triangle);
        }
    }

    // Compute the number of solid components in the alpha shape
    int num_components = 0;
    std::vector<bool> visited(triangles.size(), false);
    for (int i = 0; i < triangles.size(); ++i) {
        if (!visited[i]) {
            num_components++;
            std::stack<int> stack;
            stack.push(i);
            while (!stack.empty()) {
                int index = stack.top();
                stack.pop();
                if (!visited[index]) {
                    visited[index] = true;
                    for (int j = 0; j < triangles.size(); ++j) {
                        if (!visited[j] && triangles[index].has_common_edge(triangles[j])) {
                            stack.push(j);
                        }
                    }
                }
            }
        }
    }

    return num_components;
